-- 99_verification.sql | DIALECT: common (GENERATED by scripts/gen-snowflake.js - do not edit)
-- One result table: download as CSV and compare to the independent pandas verifier. Credit price assumed 3.00.
SELECT metric, actual, expected_from_pandas,
       CASE WHEN ABS(actual - expected_from_pandas) < 0.0051 THEN 'PASS' ELSE 'FAIL' END AS status
FROM (
SELECT 'raw_rows' AS metric, CAST((SELECT COUNT(*) FROM RAW_REPORT_SNAPSHOTS) AS DOUBLE) AS actual, CAST(2000 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'clean_rows' AS metric, CAST((SELECT COUNT(*) FROM CLEAN_SNAPSHOTS) AS DOUBLE) AS actual, CAST(1976 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'quarantined_rows' AS metric, CAST((SELECT COUNT(*) FROM DQ_QUARANTINE) AS DOUBLE) AS actual, CAST(24 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'orphan_owner_rows' AS metric, CAST((SELECT affected_rows FROM V_DQ_SUMMARY WHERE defect_code = 'ORPHAN_OWNER_ROWS') AS DOUBLE) AS actual, CAST(245 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'orphaned_now' AS metric, CAST((SELECT COUNT(*) FROM V_ORPHANS_NOW) AS DOUBLE) AS actual, CAST(14 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'latency_gt_15s_rows' AS metric, CAST((SELECT affected_rows FROM V_DQ_SUMMARY WHERE defect_code = 'LATENCY_GT_15S') AS DOUBLE) AS actual, CAST(1490 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'cost_per_view_outliers' AS metric, CAST((SELECT affected_rows FROM V_DQ_SUMMARY WHERE defect_code = 'COST_PER_VIEW_OUTLIERS') AS DOUBLE) AS actual, CAST(27 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'peak_gt_views_rows' AS metric, CAST((SELECT affected_rows FROM V_DQ_SUMMARY WHERE defect_code = 'PEAK_GT_MONTHLY_VIEWS') AS DOUBLE) AS actual, CAST(93 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'clean_credit_total' AS metric, CAST((SELECT ROUND(SUM(credits_direct), 2) FROM REPORT_CREDIT_ATTRIBUTION) AS DOUBLE) AS actual, CAST(1206352.48 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'negative_credit_sum' AS metric, CAST((SELECT ROUND(SUM(raw_value), 2) FROM DQ_QUARANTINE) AS DOUBLE) AS actual, CAST(-161.04 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'fleet_unit_cost_usd' AS metric, CAST((SELECT ROUND(unit_cost_per_view_usd, 4) FROM FLEET_UNIT_ECONOMICS) AS DOUBLE) AS actual, CAST(2.434 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'unit_cost_median_usd' AS metric, CAST((SELECT ROUND(MEDIAN(unit_cost_per_view_usd), 4) FROM REPORT_UNIT_ECONOMICS) AS DOUBLE) AS actual, CAST(2.4297 AS DOUBLE) AS expected_from_pandas
UNION ALL
SELECT 'reconciliation_failed_checks' AS metric, CAST((SELECT COUNT(*) FROM RECONCILIATION_CHECKS WHERE passed = FALSE) AS DOUBLE) AS actual, CAST(0 AS DOUBLE) AS expected_from_pandas
) t
ORDER BY metric;
